SELECT id, cluster_name, cluster_type, cluster_status, health_status, health_checked_at, metadata, create_time, update_time, is_deleted FROM cluster_info
is_deleted = 0
AND cluster_name LIKE CONCAT('%', #{query.clusterName}, '%')
AND cluster_type = #{query.clusterType}
AND cluster_status = #{query.clusterStatus}
ORDER BY create_time DESC
